-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: the four loan-dollar columns were bare try_to_double()
-- calls -- unguarded against a stray 'nan' string parsing to the float NaN
-- and poisoning any sum/average downstream. No staging model matches this
-- source: models/staging/fed_sba_ppp reads a DIFFERENT landing table
-- (FED_SBA_PPP, the full/no-threshold loan file, not the 150k-plus cut) and
-- is itself an uncast "minimal_staging" passthrough, so wrapped the four bare
-- casts in place with stg_float instead of swapping to ref().

with source as (
    select * from {{ source('ripple_raw', 'FED_SBA_PPP_LOANS_150K_PLUS') }}
)

